<script setup lang="ts">
import {onMounted,ref} from 'vue';
import type {InsuranceSettings,InsuranceProductConfig,BackendRecord} from '@kuaixie/sdk';
import {uiErrorMessage} from '@kuaixie/i18n';
import {createAdminApi} from '../api/client';
const api=createAdminApi(),settings=ref<InsuranceSettings|null>(null),applications=ref<BackendRecord[]>([]),busy=ref(false),error=ref('');
const blank=():InsuranceProductConfig=>({id:'',insurerCode:'',insurerName:'',name:'',kind:'',adapter:'',providerProductCode:'',credentialPrefix:'',termsUrl:'',exclusionsUrl:'',claimsUrl:'',serviceHosts:[],checkoutHosts:[],enabled:false});const draft=ref(blank()),serviceHosts=ref(''),checkoutHosts=ref('');
async function load(){busy.value=true;error.value='';try{settings.value=await api.insurance.settings();applications.value=await api.insurance.adminApplications()}catch(e){error.value=uiErrorMessage(e)}finally{busy.value=false}}
function company(event:Event){const value=(event.target as HTMLSelectElement).value;const item=settings.value?.directory.find(item=>item.code===value);if(item){draft.value.insurerCode=item.code;draft.value.insurerName=item.name}}
function edit(product:InsuranceProductConfig){draft.value={...product};serviceHosts.value=product.serviceHosts.join(',');checkoutHosts.value=product.checkoutHosts.join(',')}
function reset(){draft.value=blank();serviceHosts.value='';checkoutHosts.value=''}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const hosts=(value:string)=>value.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);await api.insurance.saveProduct({...draft.value,id:draft.value.id||crypto.randomUUID(),serviceHosts:hosts(serviceHosts.value),checkoutHosts:hosts(checkoutHosts.value)});reset();await load()}catch(e){error.value=uiErrorMessage(e)}finally{busy.value=false}}
onMounted(()=>{void load()});
</script>
<template><section class="insurance-settings"><h2>{{$t('insurance.settings')}}</h2><p>{{$t('insurance.configurationHelp')}}</p><p>{{$t('insurance.boundary')}}</p><p v-if="error" role="alert">{{error}}</p><button :disabled="busy" @click="load">{{$t('common.retry')}}</button><template v-if="settings"><select @change="company"><option value="">{{$t('insurance.directory')}}</option><option v-for="item in settings.directory" :key="item.code" :value="item.code">{{item.name}}</option></select><form @submit.prevent="save"><label>{{$t('insurance.insurerCode')}}<input v-model="draft.insurerCode" maxlength="64" required/></label><label>{{$t('insurance.insurerName')}}<input v-model="draft.insurerName" maxlength="200" required/></label><label>{{$t('insurance.productName')}}<input v-model="draft.name" maxlength="200" required/></label><label>{{$t('insurance.kind')}}<input v-model="draft.kind" maxlength="64" required/></label><label>{{$t('insurance.adapter')}}<input v-model="draft.adapter" maxlength="64" required/></label><label>{{$t('insurance.providerProductCode')}}<input v-model="draft.providerProductCode" maxlength="128" required/></label><label>{{$t('insurance.credentialPrefix')}}<input v-model="draft.credentialPrefix" maxlength="40" pattern="[A-Z][A-Z0-9_]{2,39}" required/></label><label>{{$t('insurance.serviceHosts')}}<input v-model="serviceHosts" required/></label><label>{{$t('insurance.checkoutHosts')}}<input v-model="checkoutHosts" required/></label><label>{{$t('insurance.terms')}}<input v-model="draft.termsUrl" type="url" required/></label><label>{{$t('insurance.exclusions')}}<input v-model="draft.exclusionsUrl" type="url" required/></label><label>{{$t('insurance.claims')}}<input v-model="draft.claimsUrl" type="url" required/></label><label><input v-model="draft.enabled" type="checkbox" :disabled="!settings.adapters.some(item=>item.id===draft.adapter&&item.insurerCode===draft.insurerCode)"/>{{$t('insurance.enable')}}</label><button :disabled="busy">{{$t('account.save')}}</button><button type="button" @click="reset">{{$t('product.cancel')}}</button></form><article v-for="product in settings.products" :key="product.id"><strong>{{product.insurerName}} · {{product.kind}} · {{product.name}}</strong><span>{{product.enabled?$t('insurance.enabled'):$t('insurance.notConnected')}}</span><button :disabled="busy" @click="edit(product)">{{$t('product.edit')}}</button></article><h3>{{$t('insurance.applications')}}</h3><article v-for="item in applications" :key="String(item.id)"><strong>{{item.order_id}}</strong><span>{{item.insurer_code}} · {{item.status}} · {{item.policy_number||''}}</span><small>{{item.last_error_code||''}}</small></article></template></section></template>
<style scoped>.insurance-settings{padding:24px;border:1px solid #cbd5e1;border-radius:18px;margin:20px 0;background:var(--kx-surface,#fff)}.insurance-settings p{font-size:13px;line-height:1.7}.insurance-settings form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin:20px 0}.insurance-settings label{display:flex;flex-direction:column;gap:6px;font-size:13px}.insurance-settings input,.insurance-settings select{padding:10px;border:1px solid #cbd5e1;border-radius:8px}.insurance-settings button{padding:10px 14px;border:0;border-radius:8px;background:#0e7490;color:white}.insurance-settings article{display:flex;gap:16px;flex-wrap:wrap;border-top:1px solid #e2e8f0;padding:14px 0}@media(max-width:650px){.insurance-settings form{grid-template-columns:1fr}}</style>
